def format_summary(notes):
    """Format a summary of notes."""
    if not notes:
        return "No notes to summarize."
    summary = ""
    for note in notes:
        summary += f"- {note['title']}: {note['content']}
"
    summary += "\n\nTag Frequency Summary:\n"
    tag_counts = {}  # Dictionary to store tag frequencies
    for note in notes:
        for tag in note.get('tags', []):
            tag_counts[tag] = tag_counts.get(tag, 0) + 1
    for tag, count in tag_counts.items():
        summary += f"{tag}: {count}\n"
    return summary

